// Generated by `manage.py bazis_front screens` from the packages and the fields of spec/product.yaml:
// never edit it, change the specs and generate it again.

import type { ReactNode } from 'react';

import { useToken } from '@/app/session';
import { CAPABILITIES } from '@/bazis/generated/contract';
import { SocketProvider } from '@/bazis/react/ws';
import { DatePickerProvider } from '@/bazis/ui/date-picker';
import { FileFieldProvider } from '@/bazis/ui/file-field';
import { MapProvider } from '@/bazis/ui/map';

/**
 * The providers that the packages and the fields of the product need, around the router: the
 * socket of bazis-ws (with the token of the session), the upload of the files (that of a guest
 * without a session), the maps of the points and the pickers of the dates.
 */
export function GeneratedProviders({ children }: { children: ReactNode }) {
  const token = useToken();
  return (
    <SocketProvider path={CAPABILITIES.ws?.path ?? null} token={token}>
      <FileFieldProvider guest={token === null}>
        <MapProvider>
          <DatePickerProvider>{children}</DatePickerProvider>
        </MapProvider>
      </FileFieldProvider>
    </SocketProvider>
  );
}
